#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>
#include <inttypes.h>

static long long ll_abs(long long x) {
    if (x == LLONG_MIN) {
        errno = ERANGE;
        return 0;
    }
    return x < 0 ? -x : x;
}

static long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

static long long lcm_ll(long long a, long long b, long long g, int *overflow) {
    __int128 part = (__int128)(a / g) * (__int128)b;
    if (part > LLONG_MAX) {
        *overflow = 1;
        return 0;
    }
    *overflow = 0;
    return (long long)part;
}

static int parse_number(const char *s, long long *out) {
    char *endptr = NULL;
    errno = 0;
    long long val = strtoll(s, &endptr, 10);
    if (errno != 0 || endptr == s || *endptr != '\0')
        return 0;
    *out = val;
    return 1;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    long long a_raw, b_raw;
    if (!parse_number(argv[1], &a_raw) || !parse_number(argv[2], &b_raw)) {
        puts("BAD_INPUT");
        return 0;
    }
    if (a_raw == LLONG_MIN || b_raw == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long long a = ll_abs(a_raw);
    long long b = ll_abs(b_raw);
    if (errno == ERANGE) {
        puts("OVERFLOW");
        return 0;
    }
    const long long MAX_VAL = 1000000LL;
    if (a > MAX_VAL || b > MAX_VAL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (a == 0 && b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long long g = gcd_ll(a, b);
    int overflow = 0;
    long long l = lcm_ll(a, b, g, &overflow);
    if (overflow) {
        puts("OVERFLOW");
        return 0;
    }
    printf("gcd=%" PRId64 " lcm=%" PRId64 "\n", g, l);
    return 0;
}
